#include <cstring>
#include <utility>

class Buffer {
    char* data;
public:
    Buffer(const char* s) : data(new char[std::strlen(s) + 1]) { std::strcpy(data, s); }
    ~Buffer() { delete[] data; }                                   // 1
    Buffer(const Buffer& o) : Buffer(o.data) {}                    // 2
    Buffer& operator=(const Buffer& o) {                           // 3
        if (this != &o) { Buffer tmp(o); std::swap(data, tmp.data); }
        return *this;
    }
    Buffer(Buffer&& o) noexcept : data(std::exchange(o.data, nullptr)) {}   // 4
    Buffer& operator=(Buffer&& o) noexcept {                       // 5
        std::swap(data, o.data);
        return *this;
    }
};

int main() { Buffer b("hello"); }

