#include <condition_variable>
#include <iostream>
#include <mutex>
#include <thread>

std::mutex m;
std::condition_variable cv;
bool ready = false;

int main() {
    std::thread consumer([] {
        std::unique_lock<std::mutex> lock(m);
        cv.wait(lock, [] { return ready; });     // sleeps until ready is true
        std::cout << "got the signal" << std::endl;
    });

    {
        std::lock_guard<std::mutex> lock(m);
        ready = true;
    }
    cv.notify_one();
    consumer.join();
}

