int main() {
    using namespace std::chrono_literals;

    std::jthread worker([](std::stop_token st) {
        while (!st.stop_requested()) {
            std::cout << "working..." << std::endl;
            std::this_thread::sleep_for(100ms);
        }
        std::cout << "stopped" << std::endl;
