int main() {
    std::vector<int> a{1, 2, 3};
    std::vector<std::string> b{"x", "y", "z"};

    for (auto [i, v] : a | std::views::enumerate)
        std::cout << i << ":" << v << " ";
    std::cout << std::endl;

    for (auto [n, s] : std::views::zip(a, b))
        std::cout << n << s << " ";
    std::cout << std::endl;

    auto squares = a
        | std::views::transform([](int n) { return n * n; })
        | std::ranges::to<std::vector>();
    std::cout << squares.size() << std::endl;

    for (auto chunk : std::views::iota(1, 8) | std::views::chunk(3)) {
        for (int x : chunk) std::cout << x << " ";
        std::cout << "| ";
    }
    std::cout << std::endl;
}

#include <generator>
#include <iostream>

std::generator<int> count(int n) {
    for (int i = 0; i < n; ++i)
        co_yield i;               // pause, hand out a value
}

std::generator<unsigned long long> fibonacci() {
    unsigned long long a = 0, b = 1;
    while (true) {
        co_yield a;
        auto next = a + b;
        a = b;
        b = next;
    }
}

int main() {
    for (int x : count(5)) std::cout << x << " ";
    std::cout << std::endl;

    int taken = 0;
    for (auto f : fibonacci()) {
        std::cout << f << " ";
        if (++taken == 10) break;
    }
    std::cout << std::endl;
}

#include <iostream>
