std::optional<int> parse(const std::string& s) {
    if (s.empty()) return std::nullopt;
    return std::stoi(s);
}

int main() {
    auto r = parse("21")
        .transform([](int x) { return x * 2; })
        .and_then([](int x) -> std::optional<int> {
            return x > 10 ? std::optional<int>(x) : std::nullopt;
        });
    std::cout << r.value_or(-1) << std::endl;   // 42

    auto none = parse("").or_else([] { return std::optional<int>(0); });
    std::cout << *none << std::endl;            // 0
}

#include <iostream>

constexpr int pick() {
    if consteval { return 1; }     // compile-time evaluation
    else         { return 2; }     // run-time evaluation
}

struct Add {
    static int operator()(int a, int b) { return a + b; }
};

int main() {
    constexpr int c = pick();      // 1
    int r = pick();                // 2 (run-time call)

    auto square = [](int x) static { return x * x; };

    std::cout << c << r << Add{}(2, 3) << square(4) << std::endl;
}

